teresting_facts": ["Rhinoceros based on real animal", "Tower originally stood in middle of river—shoreline shifted", "Dürer's famous woodcut based on same rhino"]}	[{"shot": "Classic tower with family", "when": "Morning light", "where": "Plaza facing decorated façade"}, {"tip": "Capture discovery moment", "shot": "Kids finding rhinoceros", "where": "Western side at rhino carving"}]	{"cost": {"adult": "N/A (closed)", "child": "N/A", "family_total": "FREE exterior"}, "tips": ["Tower CLOSED until Spring 2026", "Famous rhinoceros on western tower base—scavenger hunt!"], "hours": "CURRENTLY CLOSED FOR RESTORATION until Spring 2026. Exterior viewable anytime.", "stroller": "Exterior approach is flat and stroller-friendly.", "reservation": {"required": false}, "time_needed": "20-30 minutes for exterior"}	{"area": "Belém", "address": "Av. Brasília, 1400-038 Lisboa", "latitude": 38.6916, "longitude": -9.216}	\N	2:15pm-3:00pm
